const trigger = $input.first()?.json || {};
const syntheticTimestamp = Math.floor(Date.now() / 1000);
const syntheticBody = JSON.stringify({source:'luna-hmac-selftest',probe:'synthetic',nonce:String(Date.now())});
const syntheticDelivery = 'selftest-' + String(Date.now());
return [{json:{
  ...trigger,
  _selftest_timestamp: syntheticTimestamp,
  _selftest_raw_body: syntheticBody,
  _selftest_delivery: syntheticDelivery,
}}];

const result = $input.first()?.json || {};
const expected = String(result._expected || '').trim().toLowerCase();
const suppliedValid = 'sha256=' + expected;
const suppliedInvalid = expected ? expected.slice(0, -1) + (expected.endsWith('0') ? '1' : '0') : '';
const compareHmac = (leftValue, rightValue) => {
  const leftText = String(leftValue || '').replace(/^sha256=/i, '').toLowerCase();
  const rightText = String(rightValue || '').replace(/^sha256=/i, '').toLowerCase();
  let differenceMask = leftText.length ^ rightText.length;
  const comparisonLength = Math.max(leftText.length, rightText.length);
  for (let comparisonIndex = 0; comparisonIndex < comparisonLength; comparisonIndex += 1) {
    const leftCodePoint = comparisonIndex < leftText.length ? leftText.charCodeAt(comparisonIndex) : 0;
    const rightCodePoint = comparisonIndex < rightText.length ? rightText.charCodeAt(comparisonIndex) : 0;
    differenceMask |= leftCodePoint ^ rightCodePoint;
  }
  return differenceMask === 0;
};
const validSignature = Boolean(expected) && compareHmac(suppliedValid, expected);
const invalidSignature = Boolean(expected) && !compareHmac(suppliedInvalid, expected);
const currentTimestamp = Number(result._selftest_timestamp || 0);
const expiredSignature = Math.abs(Math.floor(Date.now() / 1000) - currentTimestamp - 3600) > 300;
const staticData = $getWorkflowStaticData('global');
staticData.selftestDeliveries = staticData.selftestDeliveries || {};
const deliveryKey = String(result._selftest_delivery || '');
const firstAttempt = !staticData.selftestDeliveries[deliveryKey];
staticData.selftestDeliveries[deliveryKey] = Date.now();
const replayBlocked = firstAttempt && Boolean(staticData.selftestDeliveries[deliveryKey]);
return [{json:{
  ok:validSignature && invalidSignature && expiredSignature && replayBlocked,
  cases:{valid_signature:validSignature,invalid_signature:invalidSignature,expired_signature:expiredSignature,replay_blocked:replayBlocked},
  credential_loaded:Boolean(expected),
}}];
